// Synthetic metadata; pixel data for browser checks is generated by canvas.
function segment(marker,data){const h=Buffer.from([255,marker,0,0]);h.writeUInt16BE(data.length+2,2);return Buffer.concat([h,data]);}
function jfif(x=300,y=150,unit=1){const b=Buffer.alloc(14);b.write('JFIF\0');b[5]=1;b[6]=2;b[7]=unit;b.writeUInt16BE(x,8);b.writeUInt16BE(y,10);return segment(0xe0,b);}
function exif({x=300,y=150,unit=2,orientation=1,little=true,denominator=1,omitUnit=false}={}){
 const b=Buffer.alloc(78),u16=(at,n)=>little?b.writeUInt16LE(n,at):b.writeUInt16BE(n,at),u32=(at,n)=>little?b.writeUInt32LE(n,at):b.writeUInt32BE(n,at);
 b.write(little?'II':'MM');u16(2,42);u32(4,8);u16(8,4);
 for(const [i,tag,type,value] of [[0,0x112,3,orientation],[1,0x11a,5,62],[2,0x11b,5,70],[3,omitUnit?0x9999:0x128,3,unit]]){
  const at=10+i*12;u16(at,tag);u16(at+2,type);u32(at+4,1);if(type===3)u16(at+8,value);else u32(at+8,value);
 }
 u32(62,x);u32(66,denominator);u32(70,y);u32(74,denominator);
 return segment(0xe1,Buffer.concat([Buffer.from('Exif\0\0'),b]));
}
function jpeg(pixels=Buffer.from([255,216,255,217]),segments=[jfif()]){
 const chunks=[pixels.subarray(0,2),...segments];let at=2;
 while(at+4<=pixels.length&&pixels[at]===255&&[0xe0,0xe1].includes(pixels[at+1]))at+=2+pixels.readUInt16BE(at+2);
 chunks.push(pixels.subarray(at));return Buffer.concat(chunks);
}
module.exports={segment,jfif,exif,jpeg};
